const c="/assets/cover-OM4uVkw4.webp",n="/assets/Hmw-2sisV38O.webp",t="/assets/Crazy%208s%20Sketches-KaYt0BcM.webp",g="/assets/Idea%20Documentation-cFsZ34Ie.webp",m="/assets/Prioritization%20Matrix-a4vUEzvs.webp",s="/assets/User%20Flow-BP14Jl9u.webp",o="/assets/Eksplorasi-CZexjAXP.webp",e="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question-B8LIv9Fa.webp",a="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(1%20Upgrade)-DQC-Vrt7.webp",r="/assets/specs1-CDDGgskr.webp",u="/assets/specs2-C0ZDYSul.webp",p="/assets/specs3-CT1Ub56w.webp",l="/assets/QA-C4agIGv3.webp",d="/assets/Eksplorasi%20-%20Flitter%20On-CvxZp38d.webp",k="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(2%20User%20Information)-2uSGeVLD.webp",I="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(3%20Midtrans%20Payment)-DWWqZdVL.webp",h="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(4%20Payment%20Sucess)-xIU8pVb4.webp",y={title:"NEON UJI – Subscription-Based Question Bank",title_en:"NEON UJI – Subscription-Based Question Bank",slug:"neon-uji",isActive:!0,statusBadge:"Real Case Study",statusBadge_en:"Real Case Study",roles:["Product Designer"],roles_en:["Product Designer"],timeline:"1 Week",timeline_en:"1 Week",platform:"Web Application",platform_en:"Web Application",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",organization:"PT Vortex Buana Edumedia",designTool:"Figma",techTags:["Product Design","Figma","UI/UX Design","Subscription System","Task Flow"],imageSrc:c,gallery:[c],projectUrl:"",description:"Merancang pengalaman akses Bank Soal berdasarkan tingkatan paket langganan Free, Personal, dan Business.",description_en:"Designing a subscription-based access experience for an educational question bank across Free, Personal, and Business tiers.",longDescription:`NEON UJI merupakan platform edukasi yang menyediakan fitur Bank Soal untuk mendukung kebutuhan evaluasi pembelajaran.

Dalam proyek ini, saya berperan sebagai <strong>Product Designer</strong> untuk merancang sistem pengkategorian dan pembatasan akses koleksi soal berdasarkan paket Free, Personal, dan Business. Fokus desain mencakup kejelasan hak akses, identifikasi konten premium, limited preview, serta alur upgrade paket.`,longDescription_en:`NEON UJI is an educational platform featuring a Question Bank to support learning assessment.

As <strong>Product Designer</strong>, I designed a tiered access system for question collections across Free, Personal, and Business plans — focusing on access clarity, premium content visibility, limited previews, and a seamless upgrade flow.`,sections:[{id:"overview",navTitle:"Overview",navTitle_en:"Overview",title:"Project Overview",title_en:"Project Overview",subtitle:"Subscription-Based Question Bank — PT Vortex Buana Edumedia · Apprenticeship · 1 Week",subtitle_en:"Subscription-Based Question Bank — PT Vortex Buana Edumedia · Apprenticeship · 1 Week",blocks:[{type:"text",lead:!0,content:"NEON UJI adalah platform edukasi dengan fitur Bank Soal untuk mendukung evaluasi pembelajaran. Saya berperan sebagai <strong>Product Designer</strong> — merancang sistem akses berdasarkan paket langganan Free, Personal, dan Business.",content_en:"NEON UJI is an educational platform with a Question Bank for learning assessment. As the <strong>Product Designer</strong>, I designed a tiered access system across Free, Personal, and Business subscription plans."},{type:"features_grid",title:"Project Scope",title_en:"Project Scope",features:[{title:"Subscription-Based Access",desc:"Hak akses koleksi berdasarkan tingkatan paket langganan."},{title:"Question Bank Categorization",desc:"Kategorisasi dan diferensiasi visual koleksi soal."},{title:"Premium Content Indicator",desc:"Badge dan indikator visual untuk konten premium."},{title:"Limited Preview",desc:"Teaser konten maksimal dua soal untuk paket terbatas."},{title:"Subscription Upgrade Flow",desc:"Alur pemilihan paket dan penyelesaian pembayaran."}],features_en:[{title:"Subscription-Based Access",desc:"Collection access rights based on subscription tier."},{title:"Question Bank Categorization",desc:"Visual categorization and differentiation of collections."},{title:"Premium Content Indicators",desc:"Badges and visual cues for restricted content."},{title:"Limited Content Preview",desc:"Up to two questions visible under restricted tiers."},{title:"Subscription Upgrade Flow",desc:"Plan selection and payment completion flow."}]},{type:"data_list",title:"My Contribution",title_en:"My Contribution",items:["Requirement Analysis & HMW Exploration","Crazy 8s, Idea Documentation & Prioritization Matrix","Task Flow & Interaction Design","High-Fidelity UI Design","Design Specification & Developer Handoff","Design QA & Validation"],items_en:["Requirement Analysis & HMW Exploration","Crazy 8s, Idea Documentation & Prioritization Matrix","Task Flow & Interaction Design","High-Fidelity UI Design","Design Specification & Developer Handoff","Design QA & Validation"]}]},{id:"background",navTitle:"Background & Context",navTitle_en:"Background & Context",title:"Background & Context",title_en:"Background & Context",subtitle:"Kondisi Bank Soal sebelum perubahan dan alasan sistem akses berbasis langganan dibutuhkan.",subtitle_en:"The state of Question Bank before this feature and why tiered access was needed.",blocks:[{type:"text",content:"Bank Soal di NEON UJI memungkinkan pengguna menemukan dan menggunakan koleksi soal sesuai kebutuhan evaluasi mereka. Sebelum fitur ini dikembangkan, seluruh koleksi dapat diakses tanpa pembatasan berdasarkan paket langganan.",content_en:"The Question Bank lets users discover and use question collections for their assessment needs. Before this feature, all collections were accessible without subscription-based restrictions."},{type:"callout",tone:"neutral",title:"Existing Condition",title_en:"Existing Condition",content:"Belum ada pembeda visual atau pembatasan akses antar koleksi. Pengguna tidak dapat membedakan konten gratis dan premium, dan tidak ada arahan jelas untuk melakukan upgrade paket.",content_en:"There were no visual distinctions or access restrictions between collections. Users could not differentiate free and premium content, and there was no clear path to upgrade their plans."},{type:"features_grid",title:"Why This Feature Matters",title_en:"Why This Feature Matters",features:[{title:"Access Clarity",desc:"Memperjelas koleksi mana yang dapat diakses pengguna sesuai paket aktifnya."},{title:"Subscription Visibility",desc:"Menampilkan perbedaan hak akses antar paket secara intuitif."},{title:"Upgrade Awareness",desc:"Memberikan arahan terarah saat pengguna menemui konten yang memerlukan akses lebih tinggi."}],features_en:[{title:"Access Clarity",desc:"Making it clear which collections users can access on their current plan."},{title:"Subscription Visibility",desc:"Communicating access differences across tiers in an intuitive way."},{title:"Upgrade Awareness",desc:"Guiding users toward the right upgrade path when they hit a restriction."}]},{type:"table",title:"Subscription Tier Access Scope",title_en:"Subscription Tier Access Scope",headers:["Tier","Accessible Collections"],headers_en:["Tier","Accessible Collections"],rows:[["Free","Koleksi soal gratis"],["Personal","Koleksi Free + Personal"],["Business","Koleksi sesuai hak paket Business"]],rows_en:[["Free","Free collections only"],["Personal","Free + Personal collections"],["Business","Collections under Business plan entitlements"]]}]},{id:"problem",navTitle:"Problem Definition",navTitle_en:"Problem Definition",title:"Problem Definition",title_en:"Problem Definition",subtitle:"Mengidentifikasi masalah akses dan merumuskan fokus desain melalui eksplorasi How Might We.",subtitle_en:"Identifying access friction and framing design focus through How Might We exploration.",blocks:[{type:"text",content:`Koleksi Bank Soal tidak memiliki pembeda akses berdasarkan paket langganan. Akibatnya, pengguna kesulitan memahami koleksi mana yang tersedia untuk mereka — dan konten mana yang memerlukan akses premium.

Tantangan desain: menciptakan pengalaman akses yang lebih jelas tanpa mengurangi kemudahan menemukan dan menggunakan koleksi soal.`,content_en:`Question Bank collections had no access differentiation by subscription tier. Users struggled to understand which collections were available to them — and which required premium access.

Design challenge: create a clearer access experience without making the discovery and use of question collections harder.`},{type:"callout",tone:"neutral",title:"How Might We Exploration",title_en:"How Might We Exploration",content:"Saya merumuskan sembilan pertanyaan HMW berdasarkan kebutuhan fitur dari Product Manager, mencakup aspek kejelasan akses, visibilitas paket, eksklusivitas konten, dan peluang upgrade.",content_en:"I developed nine HMW questions based on the Product Manager's feature requirements, covering access clarity, subscription visibility, premium exclusivity, and upgrade opportunities."},{type:"section_gallery",preview:n,previewCaption:"Eksplorasi 9 Pertanyaan How Might We",previewCaption_en:"How Might We Exploration – 9 Questions",gallery:[{src:n,caption:"Eksplorasi 9 Pertanyaan HMW"}],gallery_en:[{src:n,caption:"HMW Exploration – 9 Questions"}]},{type:"callout",tone:"highlight",title:"Selected HMW",title_en:"Selected HMW",content:'<strong>Bagaimana kita bisa membantu pengguna mengetahui Bank Soal mana yang dapat mereka akses sesuai paketnya?</strong><br><span class="text-xs text-neutral-400 mt-1 block">Pertanyaan ini menjadi dasar eksplorasi solusi untuk memperjelas hak akses pengguna terhadap setiap koleksi soal.</span>',content_en:'<strong>How might we help users identify which Question Bank collections they can access based on their subscription plan?</strong><br><span class="text-xs text-neutral-400 mt-1 block">This became the foundation for exploring solutions that clarify access rights across question collections.</span>'}]},{id:"exploration",navTitle:"Design Exploration",navTitle_en:"Design Exploration",title:"Requirement Analysis & Design Exploration",title_en:"Requirement Analysis & Design Exploration",subtitle:"Dari sketsa cepat Crazy 8s hingga penetapan enam solusi desain melalui prioritization matrix.",subtitle_en:"From rapid Crazy 8s sketches to six design decisions through a prioritization matrix.",blocks:[{type:"text",content:"Setelah menentukan HMW utama, saya mulai mengeksplorasi berbagai pendekatan melalui sketsa, dokumentasi ide, dan pemetaan prioritas untuk menemukan solusi yang paling relevan.",content_en:"After defining the primary HMW, I explored different approaches through sketching, idea documentation, and prioritization to find the most relevant solutions."},{type:"section_gallery",preview:t,previewCaption:"Eksplorasi Desain — Crazy 8s, Idea Documentation & Prioritization Matrix",previewCaption_en:"Design Exploration — Crazy 8s, Idea Documentation & Prioritization Matrix",gallery:[{src:t,caption:"01. Crazy 8s — Delapan Alternatif Sketsa Awal"},{src:g,caption:"02. Idea Documentation — Sticky Notes per Fitur"},{src:m,caption:"03. Prioritization Matrix — Impact vs. Effort"}],gallery_en:[{src:t,caption:"01. Crazy 8s — Eight Rapid Interface Sketches"},{src:g,caption:"02. Idea Documentation — Feature Sticky Notes"},{src:m,caption:"03. Prioritization Matrix — Impact vs. Effort"}]},{type:"features_grid",title:"Six Selected Design Solutions",title_en:"Six Selected Design Solutions",features:[{title:"1. Card Differentiation",desc:"Border visual untuk membedakan tier koleksi secara langsung."},{title:"2. Contextual Actions",desc:"Tombol aksi menyesuaikan diri secara dinamis berdasarkan status hak akses."},{title:"3. Subscription Badge",desc:"Badge paket langganan ditampilkan pada setiap kartu koleksi."},{title:"4. Access Indicator",desc:"Ikon gembok untuk koleksi yang berada di luar paket aktif pengguna."},{title:"5. Limited Preview",desc:"Maksimal dua soal ditampilkan; sisanya disamarkan dengan efek blur."},{title:"6. Package Filter",desc:"Filter koleksi berdasarkan tingkatan paket langganan."}],features_en:[{title:"1. Card Differentiation",desc:"Border styling to visually distinguish collection tiers."},{title:"2. Contextual Actions",desc:"Action buttons adapt dynamically based on the user's access status."},{title:"3. Subscription Badge",desc:"Tier badge displayed on each collection card."},{title:"4. Access Indicator",desc:"Lock icon for collections outside the user's active plan."},{title:"5. Limited Preview",desc:"Up to two questions shown; remaining content blurred."},{title:"6. Package Filter",desc:"Filter collections by subscription tier."}]}]},{id:"task-flow",navTitle:"Task Flow & Interaction",navTitle_en:"Task Flow & Interaction",title:"Task Flow & Interaction Design",title_en:"Task Flow & Interaction Design",subtitle:"Memetakan perjalanan pengguna menemukan, melihat, dan menggunakan koleksi Bank Soal.",subtitle_en:"Mapping how users discover, view, and use Question Bank collections.",blocks:[{type:"text",content:"Saya menyusun User Flow untuk memetakan perjalanan pengguna dalam dua skenario utama: pengguna yang memiliki hak akses penuh (Authorized) dan pengguna yang perlu upgrade untuk koleksi tertentu (Restricted).",content_en:"I created a User Flow mapping two primary scenarios: users with authorized access and users who need to upgrade to access restricted collections."},{type:"section_gallery",preview:s,previewCaption:"User Flow — Authorized, Restricted Access & Subscription Upgrade",previewCaption_en:"User Flow — Authorized, Restricted Access & Subscription Upgrade",gallery:[{src:s,caption:"User Flow — Authorized, Restricted Access & Subscription Upgrade"}],gallery_en:[{src:s,caption:"User Flow — Authorized, Restricted Access & Subscription Upgrade"}]},{type:"diagram",title:"Empat Tahapan Alur Pengguna",title_en:"Four Main Journey Phases",steps:[{title:"01. Accessing Question Bank",desc:"Membuka Explore, masuk ke Bank Soal, menggunakan filter paket, dan memilih koleksi."},{title:"02. Access Verification",desc:"Sistem memeriksa paket aktif pengguna: memberikan akses penuh atau menampilkan kondisi terbatas."},{title:"03. Limited Preview",desc:"Menampilkan dua soal pertama; soal selanjutnya disamarkan dengan arahan untuk upgrade."},{title:"04. Upgrade Flow",desc:"Pilih paket, selesaikan pembayaran, dan akses langsung terbuka setelah terverifikasi."}],steps_en:[{title:"01. Accessing Question Bank",desc:"Open Explore, navigate to Question Bank, use tier filters, and select a collection."},{title:"02. Access Verification",desc:"System checks the user's active plan: grant full access or show the restricted state."},{title:"03. Limited Preview",desc:"Display two sample questions; remaining content is blurred with an upgrade prompt."},{title:"04. Upgrade Flow",desc:"Select a plan, complete checkout, and access unlocks immediately after verification."}]},{type:"features_grid",title:"Access Verification – Dua Skenario",title_en:"Access Verification – Two Scenarios",features:[{title:"Authorized Access",desc:`• Detail koleksi dapat dilihat secara penuh.
• Tersedia tombol "Lihat Soal" dan "Gunakan Soal".
• Koleksi dapat digunakan sesuai hak akses paket.`},{title:"Restricted Access",desc:`• Koleksi ditampilkan dengan lock indicator.
• Tersedia limited preview maksimal dua soal.
• Tombol "Upgrade Paket" tersedia sebagai CTA.`}],features_en:[{title:"Authorized Access",desc:`• Full collection details are visible.
• "View Questions" and "Use Questions" buttons are available.
• Collections usable according to plan entitlements.`},{title:"Restricted Access",desc:`• Collections show a lock indicator.
• Limited preview of up to two questions.
• "Upgrade Plan" CTA is available.`}]}]},{id:"hifi-design",navTitle:"High-Fidelity UI",navTitle_en:"High-Fidelity UI",title:"High-Fidelity UI Design",title_en:"High-Fidelity UI Design",subtitle:"Menerapkan solusi desain ke antarmuka Bank Soal menggunakan komponen yang sudah tersedia di NEON UJI.",subtitle_en:"Translating design decisions into the Question Bank interface using NEON UJI's existing component library.",blocks:[{type:"text",content:"Fase High-Fidelity UI Design menerapkan keenam solusi yang telah ditentukan langsung ke antarmuka Bank Soal. Seluruh desain menggunakan komponen yang sudah tersedia di NEON UJI untuk menjaga konsistensi visual dan perilaku produk.",content_en:"The High-Fidelity phase translated all six selected solutions directly into the Question Bank interface. All designs used NEON UJI's existing components to maintain visual and behavioral consistency."},{type:"section_gallery",preview:o,previewCaption:"Question Bank Collection, Detail & Limited Preview, Upgrade Interaction",previewCaption_en:"Question Bank Collection, Detail & Limited Preview, Upgrade Interaction",gallery:[{src:o,caption:"01. Question Bank Collection — Card Differentiation, Badge & Filter Paket"},{src:e,caption:"02. Collection Detail & Limited Preview — Blur Effect & Informasi Paket"},{src:a,caption:"03. Upgrade Interaction — Modal Akses Premium & Tombol Upgrade"}],gallery_en:[{src:o,caption:"01. Question Bank Collection — Card Differentiation, Badge & Tier Filters"},{src:e,caption:"02. Collection Detail & Limited Preview — Blur Effect & Plan Information"},{src:a,caption:"03. Upgrade Interaction — Premium Access Modal & Upgrade CTA"}]},{type:"diagram",title:"Tiga Area Desain Utama",title_en:"Three Key Design Areas",steps:[{title:"01. Question Bank Collection",desc:"Card differentiation, subscription badge, access indicator, dan filter berdasarkan paket."},{title:"02. Collection Detail & Limited Preview",desc:"Preview dua soal, efek blur pada konten terkunci, dan informasi paket yang diperlukan."},{title:"03. Upgrade Interaction",desc:"Modal yang menjelaskan pembatasan akses, informasi paket, dan CTA untuk upgrade."}],steps_en:[{title:"01. Question Bank Collection",desc:"Card differentiation, subscription badge, access indicator, and tier-based filters."},{title:"02. Collection Detail & Limited Preview",desc:"Two-question preview, blur on restricted content, and required plan information."},{title:"03. Upgrade Interaction",desc:"Modal explaining access restrictions, plan details, and a clear upgrade CTA."}]}]},{id:"handoff",navTitle:"Design Specification",navTitle_en:"Design Specification",title:"Design Specification & Developer Handoff",title_en:"Design Specification & Developer Handoff",subtitle:"Mendokumentasikan aturan komponen, kondisi akses, dan perilaku interaksi melalui anotasi Figma.",subtitle_en:"Documenting component rules, access conditions, and interaction behaviors via Figma annotations.",blocks:[{type:"text",content:"Setelah menyelesaikan High-Fidelity UI, saya mendokumentasikan aturan desain melalui anotasi langsung pada file Figma. Tujuannya: setiap keputusan desain dapat dipahami secara kontekstual oleh developer, tanpa perlu interpretasi tambahan.",content_en:"After completing High-Fidelity UI, I documented design rules through annotations directly in Figma. The goal: every design decision is immediately understandable to developers, without additional interpretation."},{type:"section_gallery",preview:r,previewCaption:"Collection & Sorting Rules, Upgrade Modal, Preview & Access Rules",previewCaption_en:"Collection & Sorting Rules, Upgrade Modal, Preview & Access Rules",gallery:[{src:r,caption:"01. Collection & Sorting Rules — Urutan Koleksi & Perilaku Filter"},{src:u,caption:"02. Upgrade Modal Specification — Personal & Business Upsell"},{src:p,caption:"03. Preview & Access Rules — Batasan Preview & Kondisi Akses"}],gallery_en:[{src:r,caption:"01. Collection & Sorting Rules — Collection Order & Filter Behavior"},{src:u,caption:"02. Upgrade Modal Specification — Personal & Business Upsell"},{src:p,caption:"03. Preview & Access Rules — Preview Limits & Access Conditions"}]},{type:"diagram",title:"Tiga Dokumen Spesifikasi Utama",title_en:"Three Core Specification Documents",steps:[{title:"01. Collection & Sorting Rules",desc:"Aturan urutan koleksi berdasarkan paket pengguna, perilaku filter, dan tombol aksi kontekstual."},{title:"02. Upgrade Modal Specification",desc:"Paket Business memicu Business Upsell Modal; paket Personal memicu Personal Upsell Modal. Informasi dan CTA menyesuaikan pilihan."},{title:"03. Preview & Access Rules",desc:"Preview dibatasi maksimal dua soal; konten selanjutnya tidak ditampilkan. Informasi paket yang diperlukan ditampilkan secara jelas."}],steps_en:[{title:"01. Collection & Sorting Rules",desc:"Collection ordering by user tier, filter behavior, and contextual action buttons."},{title:"02. Upgrade Modal Specification",desc:"Business triggers Business Upsell; Personal triggers Personal Upsell. Info and CTAs adapt to the selected upgrade."},{title:"03. Preview & Access Rules",desc:"Preview capped at two questions; remaining content hidden. Required plan info displayed clearly."}]}]},{id:"qa-validation",navTitle:"Design QA & Validation",navTitle_en:"Design QA & Validation",title:"Design QA & Validation",title_en:"Design QA & Validation",subtitle:"Memastikan hasil implementasi sesuai dengan rancangan Figma dan standar kualitas antarmuka.",subtitle_en:"Ensuring implementation aligns with Figma designs and established interface quality standards.",blocks:[{type:"text",content:"Setelah Developer Handoff, saya melakukan Design QA menggunakan checklist untuk memastikan implementasi sesuai dengan desain Figma. Pemeriksaan mencakup aspek visual, aksesibilitas, interaksi, konten, dan responsivitas.",content_en:"Post Developer Handoff, I conducted Design QA using a structured checklist to verify implementation against Figma designs. The review covered visual consistency, accessibility, interaction behavior, content, and responsiveness."},{type:"features_grid",title:"Tiga Area Fokus Pemeriksaan",title_en:"Three QA Focus Areas",features:[{title:"01. Visual Consistency & UI Review",desc:"Component accuracy, margin & padding, icon & asset, color palette, typography."},{title:"02. Behavior & Accessibility",desc:"Interactive states (hover, active, focus, disabled), contrast ratio, responsiveness."},{title:"03. Content & Interface States",desc:"Copywriting, empty states, placeholders, form validation & error messages."}],features_en:[{title:"01. Visual Consistency & UI Review",desc:"Component accuracy, margin & padding, icon & asset, color palette, typography."},{title:"02. Behavior & Accessibility",desc:"Interactive states (hover, active, focus, disabled), contrast ratio, responsiveness."},{title:"03. Content & Interface States",desc:"Copywriting, empty states, placeholders, form validation & error messages."}]},{type:"section_gallery",preview:l,previewCaption:"Design QA Checklist — 11 Pemeriksaan Berstatus Passed",previewCaption_en:"Design QA Checklist — 11 Checks Marked as Passed",gallery:[{src:l,caption:"Design QA Checklist — 11 Pemeriksaan Berstatus Passed"}],gallery_en:[{src:l,caption:"Design QA Checklist — 11 Checks Marked as Passed"}]},{type:"callout",tone:"highlight",title:"QA Result",title_en:"QA Result",content:"Dari dokumentasi checklist yang ditampilkan, terdapat <strong>11 pemeriksaan dengan status Passed</strong>. Seluruh item yang tercantum pada checklist tersebut memenuhi kriteria yang telah ditetapkan.",content_en:"The displayed QA checklist shows <strong>11 checks, all marked as Passed</strong>. Every listed item met the defined acceptance criteria."},{type:"callout",tone:"neutral",content:"<em>Hasil ini mencerminkan item checklist yang didokumentasikan, bukan pengujian kegunaan independen atau metrik bisnis.</em>",content_en:"<em>This reflects documented checklist items, not independent usability testing or business metrics.</em>"}]},{id:"final-solution",navTitle:"Final Solution & Learnings",navTitle_en:"Final Solution & Learnings",title:"Final Solution & Learnings",title_en:"Final Solution & Learnings",subtitle:"Empat solusi desain utama, tampilan akhir antarmuka, dan refleksi dari proses pengerjaan proyek.",subtitle_en:"Four core design solutions, final interface showcase, and retrospective learnings.",blocks:[{type:"features_grid",title:"Four Key Design Solutions",title_en:"Four Key Design Solutions",features:[{title:"01. Subscription-Based Categorization",desc:"Koleksi Bank Soal dikelompokkan berdasarkan paket Free, Personal, dan Business."},{title:"02. Clear Access Indicators",desc:"Badge dan indikator visual membedakan koleksi yang dapat diakses dan yang terkunci."},{title:"03. Limited Content Preview",desc:"Preview maksimal dua soal tersedia sebelum pengguna melakukan upgrade."},{title:"04. Contextual Upgrade Experience",desc:"Informasi paket dan jalur upgrade tersedia sesuai kebutuhan akses pengguna."}],features_en:[{title:"01. Subscription-Based Categorization",desc:"Question Bank collections organized across Free, Personal, and Business tiers."},{title:"02. Clear Access Indicators",desc:"Badges and visual cues distinguish accessible from restricted collections."},{title:"03. Limited Content Preview",desc:"Up to two questions visible before users upgrade their subscription."},{title:"04. Contextual Upgrade Experience",desc:"Plan details and upgrade paths presented based on the user's access needs."}]},{type:"section_gallery",preview:d,previewCaption:"Final Interface — Question Bank, Limited Preview & Alur Upgrade Lengkap",previewCaption_en:"Final Interface — Question Bank, Limited Preview & End-to-End Upgrade Flow",gallery:[{src:d,caption:"Final Interface — Question Bank dengan Filter Paket Aktif"},{src:e,caption:"Collection Detail — Limited Preview & Konten Terkunci"},{src:a,caption:"Upgrade Flow — Langkah 1: Modal Penawaran Paket"},{src:k,caption:"Upgrade Flow — Langkah 2: Konfirmasi Data Pengguna"},{src:I,caption:"Upgrade Flow — Langkah 3: Gateway Pembayaran Midtrans"},{src:h,caption:"Upgrade Flow — Langkah 4: Pembayaran Berhasil & Akses Terbuka"}],gallery_en:[{src:d,caption:"Final Interface — Question Bank with Active Tier Filters"},{src:e,caption:"Collection Detail — Limited Preview & Restricted Content"},{src:a,caption:"Upgrade Flow — Step 1: Plan Offer Modal"},{src:k,caption:"Upgrade Flow — Step 2: User Information Confirmation"},{src:I,caption:"Upgrade Flow — Step 3: Midtrans Payment Gateway"},{src:h,caption:"Upgrade Flow — Step 4: Payment Success & Access Unlocked"}]},{type:"data_list",title:"Key Learnings",title_en:"Key Learnings",items:["Problem Framing — Menerjemahkan kebutuhan produk menjadi masalah desain yang spesifik dan dapat dikerjakan.","Design Exploration — Eksplorasi berbagai alternatif sebelum menetapkan solusi membantu menemukan pendekatan yang lebih tepat.","Interaction Design — Merancang untuk berbagai kondisi akses dan respons sistem memerlukan pertimbangan yang menyeluruh.","Design Collaboration — Spesifikasi yang jelas dan anotasi kontekstual memudahkan developer menerjemahkan keputusan desain."],items_en:["Problem Framing — Translating product needs into specific, actionable design problems is foundational.","Design Exploration — Exploring alternatives before committing to a direction leads to better-fit solutions.","Interaction Design — Designing for multiple access states and system responses requires comprehensive consideration.","Design Collaboration — Clear specifications and contextual annotations help developers implement design decisions accurately."]}]},{id:"acknowledgements",navTitle:"Acknowledgements",navTitle_en:"Acknowledgements",title:"Acknowledgements",title_en:"Acknowledgements",subtitle:"Terima kasih kepada mentor dan PT Vortex Buana Edumedia atas bimbingan dan kesempatan selama proyek.",subtitle_en:"Gratitude to my mentor and PT Vortex Buana Edumedia for guidance and the opportunity throughout the project.",blocks:[{type:"callout",tone:"highlight",content:`Saya mengucapkan terima kasih kepada mentor yang telah memberikan arahan, bimbingan, dan masukan selama proses pengerjaan proyek ini.

Terima kasih juga kepada <strong>PT Vortex Buana Edumedia</strong> atas kesempatan, kepercayaan, dan pengalaman berkontribusi langsung dalam pengembangan produk digital.

Pengalaman ini menjadi bagian berharga dalam perjalanan saya berkembang sebagai <strong>Product Designer</strong>.`,content_en:`I would like to express my sincere gratitude to my mentor for the guidance, support, and valuable feedback throughout this project.

I am also grateful to <strong>PT Vortex Buana Edumedia</strong> for the opportunity and trust to learn and contribute directly to a real digital product.

This has been a meaningful milestone in my growth as a <strong>Product Designer</strong>.`}]}]},C="data:image/svg+xml;base64,",f={title:"NEON Design System – Standarisasi Komponen & Token",title_en:"NEON Design System – Component Library & Design Tokens",slug:"neon-design-system",isActive:!0,statusBadge:"Design System",statusBadge_en:"Design System",roles:["Design System Lead","UI Designer"],roles_en:["Design System Lead","UI Designer"],description:"Sistem desain terpadu untuk platform NEON UJI: standarisasi token warna, skala tipografi, library komponen interaktif, dokumentasi spesifikasi, dan panduan developer handoff.",description_en:"A unified design system for the NEON UJI platform: design tokens, typography hierarchy, reusable interactive component library, documentation, and handoff guidelines.",longDescription:"NEON Design System dibangun untuk memastikan konsistensi visual, efisiensi kerja tim lintas disiplin, dan kecepatan implementasi frontend pada produk NEON UJI (PT Vortex Buana Edumedia). Mencakup arsitektur token (warna netral dan semantik, spasi 4px-grid, radius, elevasi bayangan), komponen atomik hingga organisme (Buttons, Input Fields, Badges, Modals, Data Tables), serta aturan accessibility (kontras rasio WCAG). Dilengkapi dokumentasi spesifikasi interaksi, states (default, hover, focus, disabled, error), dan checklist Design QA.",longDescription_en:"NEON Design System was architected to guarantee visual consistency, cross-functional velocity, and streamlined frontend delivery across the NEON UJI ecosystem at PT Vortex Buana Edumedia. Encompasses design token architecture (semantic color systems, 4px grid spacing, radius scales, surface elevations), atomic-to-organism components (Buttons, Form Controls, Overlays, Navigation Rails), alongside WCAG accessibility compliance and comprehensive interaction state guidelines.",imageSrc:C,techTags:["Design System","Figma","UI Components","Design Tokens","Design QA"],timeline:"Jul 2026 – Okt 2026",timeline_en:"Jul 2026 – Oct 2026",platform:"Cross-Platform System (Web & Mobile)",platform_en:"Cross-Platform System (Web & Mobile)",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",projectUrl:""},i="/assets/cover-BjXXcBUM.webp",w={title:"Vitacal App – Aplikasi Kesehatan (Beta Test)",title_en:"Vitacal App – Health & Nutrition Tracker (Beta Test)",slug:"vitacal-app-aplikasi-kesehatan",statusBadge:"Beta Test",statusBadge_en:"Beta Test",roles:["UI/UX Designer","Frontend Developer","Backend Developer"],roles_en:["UI/UX Designer","Frontend Developer","Backend Developer"],isActive:!0,gallery:[i,i,i],description:"Aplikasi mobile penghitung kalori dan analisis nutrisi personal menggunakan algoritma Mifflin-St Jeor, terintegrasi Open Food Facts API dan dataset Kaggle.",description_en:"A mobile app for daily calorie calculation and personal nutritional analysis using the Mifflin-St Jeor algorithm, integrated with Open Food Facts API and Kaggle datasets.",longDescription:"Vitacal App adalah aplikasi mobile kesehatan yang membantu pengguna memahami kebutuhan kalori harian mereka secara lebih akurat dan personal. Aplikasi ini menggunakan algoritma Mifflin-St Jeor untuk menghitung BMR, BMI, serta memberikan rekomendasi dan analisis kalori berdasarkan data pribadi pengguna. Proyek ini dikembangkan mulai dari riset UI/UX di Figma, hingga implementasi Frontend menggunakan Flutter dan Backend dengan Flask serta PostgreSQL. Untuk memperkaya fungsionalitas, data pencarian makanan diambil dari dataset publik Kaggle, dan fitur pemindai barcode makanan diintegrasikan langsung dengan Open Food Facts API. Sistem autentikasi menggunakan OTP via Fonnte API untuk akses yang cepat. Fokus utama proyek ini adalah menghadirkan alat pemantau nutrisi yang kompleks secara data teknis, namun tetap memiliki antarmuka yang sangat sederhana digunakan.",imageSrc:i,techTags:["Flutter","Flask","PostgreSQL","Mifflin Algorithm","Open Food Facts API","Kaggle Dataset","Fonnte API","Figma"],timeline:"2025 - 2026",platform:"Mobile Application",platform_en:"Mobile Application",context:"Final Academic Project / Tugas Akhir",context_en:"Final Academic Project / Graduation Thesis",theChallenge:"Memahami asupan kalori harian dan menjaga berat badan ideal merupakan tantangan bagi banyak orang. Sayangnya, banyak aplikasi pencatat kalori di pasaran memiliki antarmuka yang terlalu rumit dan database makanan yang terbatas. Pengguna sering kali merasa kesulitan dan kehilangan motivasi saat harus memasukkan data makanan kemasan yang mereka konsumsi sehari-hari secara manual.",theChallenge_en:"Understanding daily calorie intake and maintaining an ideal weight is a challenge for many. Unfortunately, many calorie tracking apps on the market have interfaces that are too complex and food databases that are too limited. Users often struggle and lose motivation when they have to manually log packaged foods they consume daily.",theSolution:"Pendekatan Vitacal App berfokus pada personalisasi pengguna dan kemudahan input data. Mengandalkan algoritma <strong>Mifflin-St Jeor</strong> yang teruji klinis, aplikasi membagi sistem menjadi Frontend Flutter yang responsif dan Backend Flask. Untuk mengatasi hambatan pencatatan, sistem menarik data dari dataset publik Kaggle untuk pencarian makanan lokal, dan mengintegrasikan Open Food Facts API agar pengguna cukup melakukan scan barcode pada makanan kemasan tanpa harus mengetik manual.",theSolution_en:"The Vitacal App approach focuses on user personalization and ease of data entry. Relying on the clinically proven <strong>Mifflin-St Jeor</strong> algorithm, the app splits the system into a responsive Flutter frontend and a Flask backend. To address logging friction, the system pulls data from a public Kaggle dataset for local food searches, and integrates the Open Food Facts API so users can simply scan barcodes on packaged foods instead of typing manually.",keyFeatures:[{title:"Personalisasi & Analisis Kalori",desc:"Menghitung batas kalori harian, BMI, dan analisis riwayat berat badan secara personal dan presisi menggunakan algoritma Mifflin."},{title:"Smart Barcode Scanner",desc:"Integrasi dengan Open Food Facts API untuk mengenali dan melacak nutrisi makanan kemasan secara instan hanya dengan memindai barcode."},{title:"Pencarian Makanan Komprehensif",desc:"Database pencarian makanan yang kaya dan akurat, diolah langsung dari dataset nutrisi publik Kaggle."},{title:"Otentikasi OTP WhatsApp",desc:"Sistem login dan registrasi yang mulus, aman, dan tanpa password menggunakan nomor WhatsApp melalui integrasi Fonnte API."}],keyFeatures_en:[{title:"Personalization & Calorie Analysis",desc:"Calculates daily calorie limits, BMI, and analyzes weight history precisely using the Mifflin algorithm."},{title:"Smart Barcode Scanner",desc:"Integration with the Open Food Facts API to instantly identify and track packaged food nutrition by scanning barcodes."},{title:"Comprehensive Food Search",desc:"Rich and accurate food search database, processed directly from Kaggle public nutrition datasets."},{title:"WhatsApp OTP Authentication",desc:"Seamless, secure, passwordless registration and login using WhatsApp numbers integrated via Fonnte API."}],theImpact:"Aplikasi ini berhasil menghadirkan solusi pemantauan gizi yang sangat praktis. Integrasi API pihak ketiga (Kaggle & Open Food Facts) secara signifikan memangkas waktu proses logging makanan bagi pengguna, menjadikan aplikasi ini tidak sekadar prototipe teoretis, melainkan produk fungsional yang siap memecahkan masalah diet di dunia nyata.",theImpact_en:"This application successfully delivers a highly practical nutritional monitoring solution. Third-party API integrations (Kaggle & Open Food Facts) significantly reduced food logging time for users, making the app not just a theoretical prototype, but a functional product ready to solve real-world dietary challenges.",projectUrl:"https://github.com/ariyoaziz/vitacal_app"},A="/assets/cover-CxTBtQb_.webp",v={title:"FrameFlow – Solusi Proofing Foto Modern (Beta Test)",title_en:"FrameFlow – Modern Photo Proofing Solution (Beta Test)",slug:"frameflow",statusBadge:"Beta Test",statusBadge_en:"Beta Test",isActive:!0,roles:["UI/UX Designer","Frontend Developer"],roles_en:["UI/UX Designer","Frontend Developer"],description:"Platform delivery foto instan yang mengintegrasikan Google Drive dan WhatsApp untuk mempermudah klien memilih foto favorit tanpa ribet.",description_en:"An instant photo delivery platform integrating Google Drive and WhatsApp to simplify the photo selection process for clients.",longDescription:"FrameFlow adalah solusi proofing foto modern yang dirancang khusus untuk fotografer (Wedding, Portrait, Event, Commercial). Aplikasi ini mempercepat proses pengiriman foto ke klien. Cukup hubungkan Google Drive, buat galeri dalam hitungan detik, dan biarkan klien memilih foto favorit mereka secara interaktif. Hasil pilihan klien akan otomatis dikirimkan ke WhatsApp Anda, menghilangkan keribetan dan miskomunikasi dalam proses seleksi foto. Proyek ini masih dalam tahap beta test.",longDescription_en:"FrameFlow is a modern photo proofing solution designed specifically for photographers (Wedding, Portrait, Event, Commercial). This app speeds up the photo delivery process to clients. Simply connect Google Drive, create a gallery in seconds, and let clients choose their favorite photos interactively. The client's selections will automatically be sent to your WhatsApp, eliminating hassle and miscommunication in the photo selection process. This project is currently in the beta test stage.",imageSrc:A,techTags:["Frontend","Web App","UI/UX Design","Beta Test"],timeline:"2025",timeline_en:"2025",platform:"Web Application",platform_en:"Web Application",context:"Personal Project / Eksplorasi Frontend",context_en:"Personal Project / Frontend Exploration",projectUrl:"https://frameflow-navy.vercel.app/"},S="data:image/svg+xml;base64,",P={title:"Berworkshed – Digital Product & Creative Workshop",title_en:"Berworkshed – Digital Product & Creative Workshop",slug:"berworkshed",isActive:!0,isBuilding:!0,statusBadge:"Building",statusBadge_en:"Building",roles:["Founder","Product Designer","Developer"],roles_en:["Founder","Product Designer","Developer"],description:"Inisiatif studio mandiri dan bengkel kerja kreatif yang sedang dibangun untuk merancang solusi digital, produk web interaktif, dan eksplorasi desain terapan.",description_en:"An independent studio initiative and creative workshop currently being built to craft digital solutions, interactive web products, and applied design explorations.",longDescription:"Berworkshed adalah inisiatif studio mandiri dan wadah eksplorasi kreatif yang berfokus pada desain produk digital, rekayasa frontend modern, dan perancangan pengalaman pengguna yang berkarakter. Proyek ini dibangun dari nol sebagai laboratorium kerja untuk melahirkan produk-produk mandiri yang menyelesaikan kebutuhan nyata, mulai dari tool produktivitas, antarmuka web interaktif, hingga visual branding. Saat ini Berworkshed sedang dalam tahap pembangunan fondasi, standarisasi sistem komponen, dan pengembangan portofolio produk perdana.",longDescription_en:"Berworkshed is an independent studio initiative and creative workshop space focusing on digital product design, modern frontend engineering, and distinctive user experience craftsmanship. Built from the ground up as a working laboratory, it aims to create standalone products that solve real user needs—spanning productivity tools, interactive web interfaces, and visual branding. Currently in active development, focusing on component system standardization and inaugural product builds.",imageSrc:S,techTags:["Building","Product Design","Creative Studio","Frontend","UI/UX Design"],timeline:"2026 – Sekarang",timeline_en:"2026 – Present",platform:"Digital Studio / Lab",platform_en:"Digital Studio / Lab",context:"Independent Venture / Building in Public",context_en:"Independent Venture / Building in Public",projectUrl:""},b="/assets/cover-B3t3S3rK.webp",Z={title:"CV Builder",title_en:"CV Builder",slug:"cv-builder",statusBadge:"Web App",statusBadge_en:"Web App",roles:["Product Designer","Frontend Developer"],roles_en:["Product Designer","Frontend Developer"],isActive:!0,description:"CV Builder adalah aplikasi web client-side untuk membuat CV profesional yang terstruktur, ramah ATS, responsif, dan siap dicetak atau disimpan sebagai PDF langsung dari browser.",description_en:"CV Builder is a client-side web application for creating structured, ATS-friendly, responsive CVs that can be printed or saved as PDF directly from the browser.",longDescription:"CV Builder dirancang untuk membantu pengguna membuat CV profesional dengan proses yang cepat, terstruktur, dan tetap fleksibel. Aplikasi ini berjalan sepenuhnya di sisi client, sehingga pengguna dapat mengedit CV tanpa akun dan tanpa database. Editor CV menggunakan section yang terstruktur, menyediakan template Modern, Minimal, dan Classic, serta menampilkan preview real-time dengan format kertas A4. CV dapat langsung dicetak atau disimpan sebagai PDF melalui fitur bawaan browser. Pengguna juga dapat mengimpor dan mengekspor data CV dalam format JSON agar data mudah dipindahkan dan dicadangkan. Dukungan bahasa Indonesia dan Inggris, tampilan yang responsif untuk desktop, tablet, dan mobile, security headers, optimasi static assets, serta metadata Open Graph melengkapi pengalaman aplikasi. Untuk membantu penulisan, aplikasi menyediakan prompt AI eksternal yang dapat digunakan secara manual untuk membuat atau memperbaiki isi CV, kemudian hasil JSON-nya dapat diimpor kembali ke aplikasi. Seluruh data utama disimpan di browser menggunakan localStorage dan tidak dikirim ke server secara otomatis. Source code dikembangkan di repository privat CV-Builder-Raw, disanitasi melalui GitHub Actions ke repository publik CV-Builder, lalu dideploy sebagai static export Next.js dengan output folder out menggunakan Cloudflare Workers Static Assets ke website production cv-builder.weareaap.workers.dev.",longDescription_en:"CV Builder is designed to help users create professional CVs through a fast, structured, and flexible workflow. The application runs entirely on the client side, allowing users to edit their CV without an account or database. Its structured editor includes Modern, Minimal, and Classic templates, along with a real-time A4 paper preview. CVs can be printed or saved as PDF directly through the browser. Users can also import and export CV data as JSON for easy transfer and backup. Indonesian and English language support, responsive layouts for desktop, tablet, and mobile, security headers, static asset optimization, and Open Graph metadata complete the experience. For writing assistance, the app provides external AI prompts that can be used manually to create or improve CV content, after which the resulting JSON can be imported back into the application. All primary data is stored in the browser using localStorage and is not sent to a server automatically. Source code is developed in the private CV-Builder-Raw repository, sanitized through GitHub Actions into the public CV-Builder repository, then deployed as a Next.js static export with the out output folder using Cloudflare Workers Static Assets at cv-builder.weareaap.workers.dev.",keyFeatures:[{title:"Editor CV Terstruktur",desc:"Menyusun isi CV melalui section yang jelas agar informasi mudah dikelola dan tetap ramah ATS."},{title:"Tiga Template Visual",desc:"Pilih template Modern, Minimal, atau Classic sesuai kebutuhan dan karakter profesional."},{title:"Preview A4 dan PDF",desc:"Melihat perubahan secara real-time dalam format A4, lalu mencetak atau menyimpan CV sebagai PDF langsung dari browser."},{title:"Import dan Export JSON",desc:"Memindahkan, mencadangkan, dan memulihkan data CV menggunakan format JSON."},{title:"Penyimpanan Lokal",desc:"Data utama disimpan di localStorage tanpa akun dan tanpa database, sehingga tetap berada di browser pengguna."},{title:"Prompt AI Eksternal",desc:"Membantu membuat atau memperbaiki isi CV melalui layanan AI eksternal secara manual, kemudian mengimpor hasil JSON kembali ke aplikasi."},{title:"Bilingual dan Responsif",desc:"Mendukung bahasa Indonesia dan Inggris serta nyaman digunakan di desktop, tablet, dan mobile."},{title:"Static Deployment",desc:"Dibangun sebagai static export Next.js dengan output out dan dideploy melalui Cloudflare Workers Static Assets."}],keyFeatures_en:[{title:"Structured CV Editor",desc:"Organize CV content into clear sections so information stays easy to manage and ATS-friendly."},{title:"Three Visual Templates",desc:"Choose Modern, Minimal, or Classic templates based on your needs and professional style."},{title:"A4 Preview and PDF",desc:"See changes in real time on an A4 layout, then print or save the CV as PDF directly from the browser."},{title:"JSON Import and Export",desc:"Transfer, back up, and restore CV data using the JSON format."},{title:"Local Storage",desc:"Primary data is stored in localStorage without accounts or a database, keeping it in the user's browser."},{title:"External AI Prompts",desc:"Create or improve CV content through an external AI service manually, then import the resulting JSON back into the app."},{title:"Bilingual and Responsive",desc:"Supports Indonesian and English and works comfortably on desktop, tablet, and mobile."},{title:"Static Deployment",desc:"Built as a Next.js static export with an out output folder and deployed through Cloudflare Workers Static Assets."}],imageSrc:b,gallery:[b],techTags:["Frontend","Next.js","React","TypeScript","Tailwind CSS","Radix UI","Zustand","React Hook Form","Zod","Lucide React","Sonner","date-fns","GitHub Actions","Cloudflare Workers","Static Export"],timeline:"2026",timeline_en:"2026",platform:"Web Application",platform_en:"Web Application",context:"Personal Product / Portfolio Project",context_en:"Personal Product / Portfolio Project",projectUrl:"https://cv-builder.weareaap.workers.dev"},D="/assets/cover-BOdbDh29.webp",B={title:"UI/UX Redesign – Aplikasi LinkAja (Halaman Beranda)",title_en:"UI/UX Redesign – LinkAja App (Homepage)",slug:"ui-ux-redesign-aplikasi-linkaja-halaman-beranda",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Redesain halaman beranda aplikasi LinkAja dengan fokus pada penyederhanaan antarmuka dan peningkatan navigasi pengguna.",description_en:"Redesign of the LinkAja app homepage focusing on interface simplification, logical feature grouping, and improved visual accessibility. Features a modern and clean style for better mobile navigation.",imageSrc:D,techTags:["UI/UX Design","Figma","Redesign","Mobile App"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Studi Kasus UI/UX",context_en:"UI/UX Case Study",projectUrl:"https://www.figma.com/proto/IDGtCHDIcpBGVSCdmmEieC/Desain-Ulang-APP-LInkAja?page-id=5%3A57&node-id=5-60&p=f&viewport=293%2C-18%2C1.28&t=tBMct1pVLikWEzHC-1&scaling=scale-down&content-scaling=fixed",theChallenge:"Aplikasi keuangan digital seringkali dipenuhi dengan puluhan fitur dan ikon promosi di halaman berandanya, membuat pengguna baru merasa kebingungan (<em>cognitive overload</em>) saat mencoba mencari fitur utama seperti transfer atau pembayaran.",theChallenge_en:"Digital financial apps are often packed with dozens of features and promotional icons on their homepage, causing new users to experience cognitive overload when trying to find main functions like transfers or payments.",theSolution:"Melalui proses riset desain, saya merancang ulang halaman beranda LinkAja di Figma. Saya mengelompokkan ikon berdasarkan kategori prioritas, memperbesar elemen navigasi utama, serta memberikan ruang kosong (<em>white space</em>) yang cukup agar tampilan terasa lebih bersih, modern, dan minimalis.",theSolution_en:"Through a design research process, I redesigned the LinkAja homepage in Figma. I grouped icons based on priority categories, enlarged the main navigation elements, and provided sufficient white space so that the layout feels cleaner, more modern, and minimalist.",keyFeatures:[{title:"Simplified Navigation",desc:"Mengurangi kekacauan visual dengan memprioritaskan fungsi utama aplikasi."},{title:"Modern Aesthetics",desc:"Pendekatan warna dan tipografi baru yang lebih menyegarkan mata pengguna."}],keyFeatures_en:[{title:"Simplified Navigation",desc:"Reduces visual clutter by prioritizing the app's core functionalities."},{title:"Modern Aesthetics",desc:"A refreshing new color and typography approach that is easier on the user's eyes."}],theImpact:"Desain ulang ini menghasilkan prototipe visual yang jauh lebih intuitif. Studi kasus ini membuktikan bahwa penyederhanaan antarmuka dapat secara drastis meningkatkan kenyamanan pengguna tanpa harus menghilangkan fungsionalitas bisnis dari aplikasi itu sendiri.",theImpact_en:"This redesign resulted in a significantly more intuitive visual prototype. This case study demonstrates that simplifying the interface can drastically improve user comfort without eliminating the business functionalities of the app itself."},F="/assets/cover-D4MADJYd.webp",U={title:"UI/UX Design – Website E-Commerce Alat Outdoor",title_en:"UI/UX Design – Outdoor Gear E-Commerce",slug:"ui-ux-design-website-e-commerce-alat-outdoor",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain UI/UX untuk platform e-commerce perlengkapan outdoor dengan navigasi yang intuitif dan visual yang bersih.",description_en:"Interface design for an e-commerce platform selling outdoor gear such as tents, cooking equipment, and hiking clothes. Focuses on intuitive user experience.",imageSrc:F,techTags:["UI/UX Design","Figma","E-Commerce","Prototyping"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Latihan Eksplorasi Desain",context_en:"Design Exploration Practice",projectUrl:"https://www.figma.com/design/cQTRvW7zsCFRTWT30f5tHe/e-Com?node-id=0-1&t=kskOzYVPNCdrkweR-1",theChallenge:"Situs <em>e-commerce</em> seringkali penuh sesak dengan produk, filter, dan promosi yang membuat pengguna kebingungan mencari barang spesifik, terutama untuk produk <em>niche</em> seperti peralatan <em>outdoor</em> dan <em>hiking</em>.",theChallenge_en:"E-commerce websites are often cluttered with products, filters, and promotions that confuse users looking for specific items, especially for niche products like outdoor and hiking gear.",theSolution:"Saya memusatkan desain pada navigasi yang efisien (<em>frictionless navigation</em>). Proses penyaringan kategori (tenda, alat masak, pakaian) dibuat sangat menonjol. Saya menerapkan skema warna <em>earth-tone</em> yang selaras dengan tema alam bebas, serta memberikan ruang kosong yang luas (<em>clean UI</em>) di sekitar foto produk.",theSolution_en:"I focused the design on frictionless navigation. The category filtering process (tents, cooking gear, apparel) is highly emphasized. I applied an earth-toned color palette aligned with the outdoor theme, and provided ample white space around product photos for a clean UI.",keyFeatures:[{title:"Clean Layout",desc:"Fokus langsung pada produk berkualitas tinggi tanpa distraksi elemen berlebih."},{title:"Intuitive Filtering",desc:"Sistem filter dan pencarian yang disesuaikan dengan kebiasaan pendaki/petualang."}],keyFeatures_en:[{title:"Clean Layout",desc:"Direct focus on high-quality products without the distraction of excessive UI elements."},{title:"Intuitive Filtering",desc:"Filter and search systems customized to the habits of hikers/adventurers."}],theImpact:"Menghasilkan <em>mockup</em> UI beresolusi tinggi yang siap diserahkan (<em>hand-off</em>) kepada tim <em>frontend</em>. Desain ini membuktikan kemampuan saya merangkai antarmuka penjualan yang berorientasi pada konversi (<em>conversion-centric design</em>).",theImpact_en:"Delivered a high-fidelity UI mockup ready for hand-off to the frontend team. This design demonstrates my ability to create sales interfaces focused on conversion-centric design."},j="/assets/cover-BvjOOP68.webp",M={title:"UI/UX Design – Order Food App",title_en:"UI/UX Design – Order Food App",slug:"ui-ux-design-order-food-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Konsep desain aplikasi pemesanan makanan dengan tampilan modern dan alur pemesanan yang sederhana.",description_en:"Food ordering app design concept with a clean and modern approach. Provides an easily navigable user experience.",imageSrc:j,techTags:["UI/UX Design","Figma","Mobile App","Prototype"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655317/order-food",theChallenge:"Membuat aplikasi pengantaran makanan mengharuskan kita memikirkan bagaimana pengguna bisa menemukan makanan favorit, memasukkan ke keranjang, dan melakukan <em>checkout</em> dalam jumlah ketukan (<em>taps</em>) seminimal mungkin.",theChallenge_en:"Creating a food delivery app requires thinking about how users can find their favorite food, add it to the cart, and complete checkout in as few taps as possible.",theSolution:"Desain aplikasi ini memprioritaskan fotografi makanan (<em>food imagery</em>) yang besar untuk menggugah selera pengguna. Alur pemesanan dirancang secara linier (satu arah) agar tidak membingungkan, dari halaman beranda, rincian menu, modifikasi pesanan (<em>add-ons</em>), hingga layar <em>checkout</em> akhir.",theSolution_en:"The design of this application prioritizes large food imagery to stimulate the user's appetite. The order flow is designed linearly (one-way) to avoid confusion, navigating smoothly from the homepage, menu details, order customizations (add-ons), to the final checkout screen.",keyFeatures:[{title:"Appetizing Visuals",desc:"Penataan UI yang menonjolkan visual gambar menu dengan tata letak bergaya modern."},{title:"Linear Checkout Flow",desc:"Alur pembelian yang sangat ringkas untuk mempercepat proses konversi pesanan."}],keyFeatures_en:[{title:"Appetizing Visuals",desc:"UI layout highlighting menu imagery with modern layout styles."},{title:"Linear Checkout Flow",desc:"A highly simplified buying flow to speed up the order conversion process."}],theImpact:"Konsep desain ini telah dipublikasikan di Behance dan mendapatkan apresiasi positif atas pendekatan minimalisnya yang tetap mempertahankan fungsionalitas utama aplikasi pesan antar.",theImpact_en:"This design concept was published on Behance and received positive feedback for its minimalist approach while retaining the core features of a food delivery application."},T="/assets/cover-C3v7gSjj.webp",x={title:"UI/UX Design – Coffee App",title_en:"UI/UX Design – Coffee App",slug:"ui-ux-design-coffee-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain antarmuka aplikasi pemesanan kopi dengan visual elegan dan alur pengguna yang sederhana.",description_en:"An elegant and modern coffee ordering app interface design, emphasizing user comfort. Designed using Figma.",imageSrc:T,techTags:["UI/UX Design","Figma","Mobile App","Product Design"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655381/coffee",theChallenge:"Aplikasi <em>coffee shop</em> membutuhkan sentuhan personalisasi yang kuat (seperti mengatur ukuran gelas, kadar gula, jenis susu, dan es) tanpa membuat tampilan pemesanan terasa mengintimidasi atau rumit layaknya formulir panjang.",theChallenge_en:"Coffee shop applications require a strong touch of personalization (such as adjusting cup sizes, sweetness, milk types, and ice) without making the ordering screen feel intimidating or cluttered like a long form.",theSolution:"Saya memecahkan masalah ini dengan pendekatan <em>card UI</em> dan <em>toggle buttons</em>. Pengguna dapat meracik kopi mereka melalui opsi visual yang menyenangkan secara interaktif. Skema warna yang digunakan didominasi oleh corak kopi elegan dan gaya minimalis yang mewah (<em>premium feel</em>).",theSolution_en:"I solved this problem using a card UI and toggle button approach. Users can customize their drinks interactively through pleasant visual choices. The color palette is dominated by elegant coffee shades and a luxurious minimalist styling for a premium feel.",keyFeatures:[{title:"Customization Interface",desc:"Antarmuka kustomisasi minuman (gula, es, susu) yang sangat mudah digunakan."},{title:"Premium Dark Theme",desc:"Skema warna elegan yang mencerminkan suasana kedai kopi berkelas."}],keyFeatures_en:[{title:"Customization Interface",desc:"Highly intuitive drink customization interface (sugar, ice, milk) with minimal steps."},{title:"Premium Dark Theme",desc:"An elegant color scheme reflecting the atmosphere of a classy coffee shop."}],theImpact:"Desain ini (yang juga dapat dilihat di portofolio Behance saya) merepresentasikan kapabilitas saya dalam memadukan keindahan visual estetis dengan pengalaman pengguna (<em>User Experience</em>) yang logis dan fungsional.",theImpact_en:"This design (which is also showcased on my Behance portfolio) represents my capability to blend aesthetic visual beauty with a logical, functional User Experience."},W=[y,f,w,v,P,Z,B,U,M,x];export{W as a,C as b,b as c,S as d,A as f,c as n,i as v};
